/**
 * Utility to reliably download Sunny Kumar's Resume PDF across all browsers
 */

const RESUME_BASE64 = '';

window.downloadResumePdf = async function(customFilename = 'Sunny-Kumar-Resume.pdf') {
  const filename = customFilename;

  // Strategy 1: Fetch PDF as Blob to force file download in Safari/Chrome
  const candidateUrls = [
    'assets/Sunny-Kumar-Resume.pdf',
    'assets/Sunny_Kumar_Resume.pdf',
    '/Sunny-Kumar-Resume.pdf',
    '/Sunny_Kumar_Resume.pdf',
    '/assets/Sunny-Kumar-Resume.pdf',
    'http://localhost:5050/api/cv',
    '/api/cv'
  ];

  for (const url of candidateUrls) {
    try {
      const response = await fetch(url);
      if (response.ok) {
        const blob = await response.blob();
        if (blob && blob.size > 1000) {
          const blobUrl = window.URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.style.display = 'none';
          a.href = blobUrl;
          a.download = filename;
          document.body.appendChild(a);
          a.click();
          setTimeout(() => {
            if (document.body.contains(a)) document.body.removeChild(a);
            window.URL.revokeObjectURL(blobUrl);
          }, 2000);
          return true;
        }
      }
    } catch (e) {
      // continue
    }
  }

  // Strategy 2: Base64 decode into Blob
  try {
    const byteCharacters = atob(RESUME_BASE64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: 'application/pdf' });
    const blobUrl = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.style.display = 'none';
    a.href = blobUrl;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      if (document.body.contains(a)) document.body.removeChild(a);
      window.URL.revokeObjectURL(blobUrl);
    }, 2000);
    return true;
  } catch (e) {
    console.warn('Base64 decode download failed:', e);
  }

  // Strategy 3: Direct link navigation
  const fallbackA = document.createElement('a');
  fallbackA.href = 'assets/Sunny-Kumar-Resume.pdf';
  fallbackA.target = '_blank';
  fallbackA.download = filename;
  document.body.appendChild(fallbackA);
  fallbackA.click();
  setTimeout(() => {
    if (document.body.contains(fallbackA)) document.body.removeChild(fallbackA);
  }, 1000);
  return false;
};
